import {NativeHomeSession} from './session.mjs';import {createUITicket} from './ui-ticket.mjs';import {loadSelectedAssets} from './assets.mjs';import {createJangmokEnvironment} from './environment.mjs';import {renderNativeHome} from './render.mjs';
const $=id=>document.getElementById(id),g=$('view').getContext('2d'),root=new URL('./',import.meta.url),ticket=createUITicket();let c,A,travel,assets={},masks={},session,environment,ready=false,active=!document.hidden,keys=new Map(),route=null,stamp=0,remainder=0,lastDraw=-Infinity;
const sha=async b=>[...new Uint8Array(await crypto.subtle.digest('SHA-256',b))].map(n=>n.toString(16).padStart(2,'0')).join(''),bytes=async(url,pin)=>{const r=await fetch(url,{cache:'no-store'});if(!r.ok)throw Error('MISSING '+url);const b=await r.arrayBuffer();if(await sha(b)!==pin)throw Error('PIN '+url);return b},image=async(url,pin)=>createImageBitmap(new Blob([await bytes(url,pin)])),makeCanvas=(w,h)=>{const x=document.createElement('canvas');x.width=w;x.height=h;return x},rgba=im=>{const cv=makeCanvas(im.width,im.height),ctx=cv.getContext('2d');ctx.drawImage(im,0,0);return ctx.getImageData(0,0,im.width,im.height).data};
function stop(message){ticket.invalidate();keys.clear();route=null;remainder=0;session?.cancel();if(message)$('message').textContent=message}
function draw(){if(!ready)return;const s=session.snapshot(),r=renderNativeHome(g,{contract:c,assets,environment,status:s,marks:$('marks').checked,supported:session.safe(s.scene,s.foot)});window.__remainingNativeHomes={...s,...r};$('status').textContent=JSON.stringify(window.__remainingNativeHomes,null,2);$('action').disabled=s.pending;$('door').value=s.doorStates[$('door-home').value]??s.doorState}
function chooseHome(id){stop();session?.dispose();session=new NativeHomeSession({contract:c,homeId:id,masks,loadScene:async target=>{if($('slow').checked)await new Promise(r=>setTimeout(r,800));return {sha256:$('bad').checked?'bad':c.sources[target].sha256}}});$('message').textContent='개발 시나리오 시작점 선택 · 문 CLOSED · 환경 시계/옵션 유지 (본편 워프 아님)';draw()}
async function action(){if(!ready||!active||session.pending)return;const mine=ticket.begin();route=null;keys.clear();const r=await session.action();if(!ticket.isCurrent(mine))return;$('message').textContent=r.ok?({enter:'신규 native 현관 진입',return:'신규 native 현관 복귀',stairs:'기존 선정 계단 좌표·도착 계약 실행'}[r.kind]+' · 본편/저장 연결0'):r.reason;draw()}
function press(id,d){if(!ready||!active)return;route=null;keys.set(id,{d,stamp:++stamp})}
function startRoute(){if(!ready||!active)return;stop();const s=session.snapshot(),want=$('route-target').value;let paths=[];if(s.scene==='exterior'){if(want==='door')paths=[session.h.exteriorDoor.approachRoute];else if(['upper','family','coastal'].includes(want))paths=Object.entries(travel.routes).filter(([key])=>key.endsWith('__'+want)).map(([,p])=>p)}else paths=Object.entries(c.floors[s.scene].routes).filter(([k])=>k.endsWith(want==='stairs'?'_stair':'_entry')).map(([,v])=>v);let found;for(const p of paths){const at=p.findIndex(v=>v[0]===s.foot[0]&&v[1]===s.foot[1]);if(at>=0){found=p.slice(at+1);break}}if(!found){$('message').textContent='현재 발점에서 이 선정 경로를 시작할 수 없습니다. 방향키로 기존 지원점에 접근하세요. 단층에는 계단이 없습니다.';return}route=found;if(!route.length){route=null;session.face(want==='door'?(s.scene==='exterior'?'up':'down'):s.facing)}$('message').textContent='기존 safe49 경로1px 이동 · 도착 후 A'}
function tick(time){const dt=ready?environment.tickRAF(time,active&&!document.hidden):0;if(ready&&active&&!document.hidden&&!session.pending){const d=[...keys.values()].sort((a,b)=>b.stamp-a.stamp)[0]?.d;if(d||route?.length){remainder+=dt*.12;let n=Math.floor(remainder);remainder-=n;while(n-->0){let direction=d;if(route?.length){const p=route[0],dx=p[0]-session.foot[0],dy=p[1]-session.foot[1];if(Math.abs(dx)+Math.abs(dy)!==1){route=null;break}direction=dx<0?'left':dx>0?'right':dy<0?'up':'down'}const r=session.move(direction);if(!r.ok){route=null;keys.clear();$('message').textContent=r.reason;break}if(route?.length){route.shift();if(!route.length){route=null;if(['door','upper','family','coastal'].includes($('route-target').value))session.face(session.scene==='exterior'?'up':'down');break}}}}else{remainder=0;session.stopGait()}}if(ready&&time-lastDraw>=50){draw();lastDraw=time}requestAnimationFrame(tick)}
try{const r=await fetch('./contract.json',{cache:'no-store'});if(!r.ok)throw Error('CONTRACT');c=await r.json();travel=JSON.parse(new TextDecoder().decode(await bytes(new URL('./travel-routes.json',root),'613102b0d36897c576e53f0b94dea08f6effcf9568bb0afe02ec4de4bf8f1368')));A=await loadSelectedAssets({contract:c,rootURL:root,bytes,image,rgba,makeCanvas,sha});assets.exterior=A.source;for(const[k,s]of Object.entries(c.sources))if(k!=='exterior')assets[k]=await image(new URL(s.path,root),s.sha256);A.actors.forEach((actor,i)=>assets['actor:'+i]=actor);for(const[k,s]of Object.entries(c.masks))masks[k]=new Uint8Array(await bytes(new URL(s.path,root),s.sha256));environment=createJangmokEnvironment(A);ready=true;for(const id of Object.keys(c.houses))$('home').add(new Option(id==='upper'?'Upper · 2층':id==='family'?'Family · 단층':'Coastal · 단층',id));$('unassigned').textContent=c.unassigned.map(h=>h.id+': '+h.reason).join('\n');chooseHome('upper')}catch(e){ready=false;g.clearRect(0,0,g.canvas.width,g.canvas.height);$('message').textContent='입력 검증 실패: '+e.message;window.__remainingNativeHomes={ready:false,error:e.message}}
$('door-home').onchange=draw;$('home').onchange=()=>{if(ready)chooseHome($('home').value)};$('reset').onclick=()=>{stop();session?.reset();draw()};$('door').onchange=()=>{stop();session?.setDoorState($('door').value,$('door-home').value);draw()};$('route').onclick=startRoute;$('cancel').onclick=()=>stop('입력·미완료 전환 취소');$('marks').onchange=draw;
const directions={ArrowUp:'up',w:'up',W:'up',ArrowDown:'down',s:'down',S:'down',ArrowLeft:'left',a:'left',A:'left',ArrowRight:'right',d:'right',D:'right'};window.addEventListener('keydown',e=>{if(['INPUT','SELECT','TEXTAREA'].includes(e.target.tagName))return;if(directions[e.key]){e.preventDefault();if(!e.repeat)press('key:'+e.code,directions[e.key])}if(['z','Z','Enter',' '].includes(e.key)){e.preventDefault();if(!e.repeat)action()}if(['Escape','x','X'].includes(e.key))stop('입력·미완료 전환 취소')});window.addEventListener('keyup',e=>{keys.delete('key:'+e.code);if(['z','Z','Enter',' '].includes(e.key))session?.releaseAction()});
for(const b of document.querySelectorAll('[data-dir]')){b.onpointerdown=e=>{e.preventDefault();b.setPointerCapture(e.pointerId);press('pointer:'+e.pointerId,b.dataset.dir)};for(const type of ['pointerup','lostpointercapture'])b.addEventListener(type,e=>keys.delete('pointer:'+e.pointerId));b.onpointermove=e=>{const r=b.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)keys.delete('pointer:'+e.pointerId)}}
$('action').onpointerdown=e=>{e.preventDefault();$('action').setPointerCapture(e.pointerId);action()};for(const type of ['pointerup','lostpointercapture'])$('action').addEventListener(type,()=>session?.releaseAction());$('action').onclick=e=>{if(e.detail===0)action().finally(()=>session?.releaseAction())};
for(const type of ['blur','pagehide','pointercancel','resize','orientationchange','popstate'])window.addEventListener(type,()=>{stop('화면/입력 변경으로 진행 중 입력 정리');if(['blur','pagehide'].includes(type)){active=false;environment?.resetFrameBaseline()}});for(const type of ['focus','pageshow'])window.addEventListener(type,()=>{active=true;environment?.resetFrameBaseline()});document.addEventListener('visibilitychange',()=>{active=!document.hidden;stop();environment?.resetFrameBaseline()});
$('day').onclick=()=>{environment?.setTime(720);draw()};$('night').onclick=()=>{environment?.setTime(1320);draw()};for(const key of ['water','lights','b1','b2','b3','b4','sort','depth','paused','demo'])$('env-'+key).onchange=()=>{environment?.setOption(key,$('env-'+key).checked);draw()};requestAnimationFrame(tick);
